+import { provenanceOf } from "./trailers.ts";
+
+describe("provenanceOf", () => {
+  describe("spoofed author attack", () => {
+    it("demotes unverified 'authored' claims to unknown", () => {
+      const trailers = new Map([["Provenance", "authored"]]);
+      const result = provenanceOf({
+        trailers,
+        authorEmail: "attacker@attacker.com",
+        verifiedAuthorEmails: new Set(["alice@company.com", "bob@company.com"]),
+      });
+      expect(result).toBe("unknown");
+    });
+
+    it("demotes 'authored' without cryptographic verification to unknown", () => {
+      const trailers = new Map([["Provenance", "authored"]]);
+      const result = provenanceOf({
+        trailers,
+        authorEmail: "alice@company.com",
+        verifiedAuthorEmails: new Set(["alice@company.com"]),
+        verifiedSignature: false,
+      });
+      expect(result).toBe("unknown");
+    });
+  });
+
+  describe("verified author", () => {
+    it("accepts 'authored' when author is verified and cryptographically signed", () => {
+      const trailers = new Map([["Provenance", "authored"]]);
+      const result = provenanceOf({
+        trailers,
+        authorEmail: "alice@company.com",
+        verifiedAuthorEmails: new Set(["alice@company.com"]),
+        verifiedSignature: true,
+      });
+      expect(result).toBe("authored");
+    });
+
+    it("accepts 'authored' when author email matches verified set and is signed", () => {
+      const trailers = new Map([["Provenance", "authored"]]);
+      const result = provenanceOf({
+        trailers,
+        authorEmail: "bob@company.com",
+        verifiedAuthorEmails: new Set(["alice@company.com", "bob@company.com"]),
+        verifiedSignature: true,
+      });
+      expect(result).toBe("authored");
+    });
+  });
+
+  describe("inherited and reconstructed", () => {
+    it("accepts 'inherited' regardless of verification", () => {
+      const trailers = new Map([["Provenance", "inherited"]]);
+      const result = provenanceOf({
+        trailers,
+      });
+      expect(result).toBe("inherited");
+    });
+
+    it("accepts 'reconstructed' regardless of verification", () => {
+      const trailers = new Map([["Provenance", "reconstructed"]]);
+      const result = provenanceOf({
+        trailers,
+      });
+      expect(result).toBe("reconstructed");
+    });
+  });
+
+  describe("fallback to unknown", () => {
+    it("returns unknown for missing trailer", () => {
+      const trailers = new Map([]);
+      const result = provenanceOf({ trailers });
+      expect(result).toBe("unknown");
+    });
+
+    it("returns unknown for invalid trailer value", () => {
+      const trailers = new Map([["Provenance", "invalid"]]);
+      const result = provenanceOf({ trailers });
+      expect(result).toBe("unknown");
+    });
+  });
+});
