 import type { Provenance } from "./grade.ts";

-export const provenanceOf = (trailers: ReadonlyMap<string, string>): Provenance => {
-  const raw = trailers.get("Provenance");
-  if (raw === "authored" || raw === "inherited" || raw === "reconstructed") return raw;
+export interface ProvenanceContext {
+  trailers: ReadonlyMap<string, string>;
+  verifiedSignature?: boolean;
+  authorEmail?: string;
+  verifiedAuthorEmails?: ReadonlySet<string>;
+}
+
+export const provenanceOf = (context: ProvenanceContext): Provenance => {
+  const trailerClaim = context.trailers.get("Provenance");
+
+  if (trailerClaim === "authored") {
+    if (context.verifiedSignature && context.authorEmail && context.verifiedAuthorEmails?.has(context.authorEmail)) {
+      return "authored";
+    }
+    return "unknown";
+  }
+
+  if (trailerClaim === "inherited" || trailerClaim === "reconstructed") {
+    return trailerClaim;
+  }
+
   return "unknown";
 };
